import { writeFile } from 'node:fs/promises';
import { NestFactory } from '@nestjs/core';
import openapiTS, { astToString } from 'openapi-typescript';
import { createApiDocument } from '../dist/api-docs.js';
import { AppModule } from '../dist/app.module.js';

const GENERATED_TYPES_URL = new URL(
  '../../../packages/contracts/src/api.generated.ts',
  import.meta.url,
);
const GENERATED_FILE_HEADER =
  '// Generated from the API DTOs by `pnpm api:types`. Do not edit this file by hand.\n\n';

// Preview mode builds the route table without creating providers, so this needs no server or database.
const app = await NestFactory.create(AppModule, { preview: true, logger: ['error'] });
const generatedTypes = astToString(await openapiTS(createApiDocument(app)));
await writeFile(GENERATED_TYPES_URL, GENERATED_FILE_HEADER + generatedTypes);
